import { CreateTokenData, createToken, getTokenStatus } from '@proton/shared/lib/api/payments';
import { PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';
import { getHostname } from '@proton/shared/lib/helpers/url';
import { Api } from '@proton/shared/lib/interfaces';

import PaymentVerificationModal from './PaymentVerificationModal';
import {
    AmountAndCurrency,
    CardPayment,
    ExistingPayment,
    PaymentTokenResult,
    TokenPaymentMethod,
    WrappedCardPayment,
    isExistingPayment,
    isTokenPaymentMethod,
} from './interface';
import { toTokenPaymentMethod } from './paymentTokenToParams';

const { STATUS_PENDING, STATUS_CHARGEABLE, STATUS_FAILED, STATUS_CONSUMED, STATUS_NOT_SUPPORTED } =
    PAYMENT_TOKEN_STATUS;

const DELAY_PULLING = 5000;

/** Opens the approval tab and polls until verification ends or is cancelled. */
export const process = (
    {
        Token,
        api,
        ApprovalURL,
        ReturnHost,
        signal,
    }: Pick<PaymentTokenResult, 'ApprovalURL' | 'ReturnHost' | 'Token'> & {
        api: Api;
        signal: AbortSignal;
    },
    pollingInterval = DELAY_PULLING
): Promise<void> => {
    const tab = window.open(ApprovalURL);

    return new Promise<void>((resolve, reject) => {
        let timer: ReturnType<typeof setTimeout> | undefined;
        let settled = false;
        let checking = false;

        const cleanup = () => {
            if (timer !== undefined) {
                clearTimeout(timer);
            }
            window.removeEventListener('message', onMessage, false);
            signal.removeEventListener('abort', onAbort);
        };

        const finish = (error?: unknown) => {
            if (settled) {
                return;
            }
            settled = true;
            cleanup();
            tab?.close();
            if (error) {
                reject(error);
            } else {
                resolve();
            }
        };

        const check = async () => {
            if (settled || checking) {
                return;
            }
            checking = true;
            try {
                const { Status } = await api({ ...getTokenStatus(Token), signal });
                if (settled) {
                    return;
                }
                if (
                    Status === STATUS_CHARGEABLE ||
                    Status === STATUS_FAILED ||
                    Status === STATUS_CONSUMED ||
                    Status === STATUS_NOT_SUPPORTED ||
                    tab?.closed
                ) {
                    finish();
                    return;
                }
                if (Status !== STATUS_PENDING) {
                    finish(new Error(c('Error').t`Unknown payment token status`));
                    return;
                }
                timer = setTimeout(check, pollingInterval);
            } catch (error) {
                finish(error);
            } finally {
                checking = false;
            }
        };

        const onMessage = (event: MessageEvent) => {
            if (getHostname(event.origin) !== ReturnHost) {
                return;
            }
            if (event.data?.cancel === '1') {
                finish();
                return;
            }
            tab?.close();
            if (timer !== undefined) {
                clearTimeout(timer);
            }
            void check();
        };

        const onAbort = () => finish();

        if (signal.aborted) {
            finish();
            return;
        }
        signal.addEventListener('abort', onAbort);
        window.addEventListener('message', onMessage, false);
        timer = setTimeout(check, pollingInterval);
    });
};

/**
