import { getCreatePaymentToken, process } from '@proton/components/containers/payments/paymentTokenHelper';
import { PAYMENT_METHOD_TYPES, PAYMENT_TOKEN_STATUS } from '@proton/shared/lib/constants';

let tab: { closed: boolean; close: () => any };

function delay(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

beforeEach(() => {
    jest.clearAllMocks();

    tab = { closed: false, close: jest.fn() };
    jest.spyOn(window, 'open').mockReturnValue(tab as any);
    jest.spyOn(window, 'removeEventListener');
    jest.spyOn(window, 'addEventListener');
});

describe('getCreatePaymentToken', () => {
    const params = { PaymentMethodID: 'saved-card' };
    const amountAndCurrency = { Amount: 100, Currency: 'EUR' as const };

    it('returns a chargeable token without verification', async () => {
        const api = jest.fn().mockResolvedValue({ Token: 'token', Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });
        const verify = jest.fn();
        const createPaymentToken = getCreatePaymentToken(verify);

        await expect(createPaymentToken({ api, params }, amountAndCurrency)).resolves.toEqual({
            Payment: { Type: PAYMENT_METHOD_TYPES.TOKEN, Details: { Token: 'token' } },
        });
        expect(verify).not.toHaveBeenCalled();
        expect(api).toHaveBeenCalledWith(expect.objectContaining({ data: { ...params, ...amountAndCurrency } }));
    });

    it('passes a pending token to the injected verifier', async () => {
        const api = jest.fn().mockResolvedValue({
            Token: 'token',
            Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING,
            ApprovalURL: 'https://example.test',
            ReturnHost: 'example.test',
        });
        const verified = { Payment: { Type: PAYMENT_METHOD_TYPES.TOKEN, Details: { Token: 'token' } } };
        const verify = jest.fn().mockResolvedValue(verified);

        await expect(getCreatePaymentToken(verify)({ api, params, mode: 'add-card' })).resolves.toBe(verified);
        expect(verify).toHaveBeenCalledWith({
            mode: 'add-card',
            Payment: undefined,
            Token: 'token',
            ApprovalURL: 'https://example.test',
            ReturnHost: 'example.test',
        });
    });

    it('rejects a failed token without verification', async () => {
        const api = jest.fn().mockResolvedValue({ Token: 'token', Status: PAYMENT_TOKEN_STATUS.STATUS_FAILED });
        const verify = jest.fn();

        await expect(getCreatePaymentToken(verify)({ api, params })).rejects.toThrow();
        expect(verify).not.toHaveBeenCalled();
    });
});

